export function Brand({surface="light",compact=false}:{surface?:"light"|"dark";compact?:boolean}){
  const src=compact?"/brand/omnira-symbol.svg":`/brand/omnira-logo-${surface}.svg`;
  return <div className={`brand ${compact?"brand-compact":""}`}><img src={src} alt="OMNIRA"/>{!compact&&<span>AI Business Operating System</span>}</div>;
}

