 useEffect(()=>{void Promise.all([can(session,"clients.read")?api.list("clients"):Promise.resolve([]),can(session,"projects.read")?api.list("projects"):Promise.resolve([]),api.dashboard(30)]).then(([c,p,d])=>{setClients(c);setProjects(p);setCurrencies((d.finance??[]).map((x:any)=>x.currencyCode));}).catch(x=>setError(apiErrorMessage(x)));},[]);
